func (b *bleveBackend) TotalDocs() int64 {
	var totalDocs int64
	b.cacheMu.RLock()
	for _, v := range b.cache {
		c, err := v.index.DocCount()
		if err != nil {
			continue
		}
		totalDocs += int64(c)
	}
	b.cacheMu.RUnlock()
	return totalDocs

